#!/usr/bin/env python3
from pathlib import Path
p=Path('Source/SingleWetSpectralRenderer.cpp')
s=p.read_text()
needle='''    const double expectedPhaseScale = twoPi * static_cast<double>(hopSize_)\n                                    / static_cast<double>(frameSize_);\n\n    const bool initialiseLayer = resetPhases || !layer.phaseInitialised;'''
insert='''    const double expectedPhaseScale = twoPi * static_cast<double>(hopSize_)\n                                    / static_cast<double>(frameSize_);\n\n    // EXPERIMENTAL_TARGET_CENTRIC_FULL_SPECTRUM_V11_PROBE\n    // One inverse spectral map for every output bin: no peak ownership, no F0,\n    // no harmonic/noise classes and no formant reconstruction. The output bin\n    // samples source position k/ratio, while its phase velocity is the measured\n    // instantaneous source frequency multiplied by the same musical ratio.\n    if (frameSize_ <= 128)\n    {\n        (void) sourceFundamentalHz;\n        (void) formantPreservation;\n        const bool initialiseExperimental = resetPhases || !layer.phaseInitialised;\n        const float energyScaleExperimental = static_cast<float>(\n            1.0 / std::sqrt(safeRatio));\n\n        for (int targetBin = 0; targetBin <= positiveBins; ++targetBin)\n        {\n            const double sourcePosition = static_cast<double>(targetBin) / safeRatio;\n            if (sourcePosition < 0.0 || sourcePosition > static_cast<double>(positiveBins))\n                continue;\n\n            const int lower = std::clamp(static_cast<int>(std::floor(sourcePosition)),\n                                         0, positiveBins);\n            const int upper = std::min(positiveBins, lower + 1);\n            const double fraction = sourcePosition - static_cast<double>(lower);\n            const std::size_t li = static_cast<std::size_t>(lower);\n            const std::size_t ui = static_cast<std::size_t>(upper);\n\n            const float magnitude = static_cast<float>(\n                (1.0 - fraction) * static_cast<double>(magnitudes_[li])\n                + fraction * static_cast<double>(magnitudes_[ui]));\n            if (magnitude <= 1.0e-12f)\n                continue;\n\n            const double sourcePhase = static_cast<double>(analysisPhases_[li])\n                + fraction * wrapPhase(static_cast<double>(analysisPhases_[ui])\n                    - static_cast<double>(analysisPhases_[li]));\n            const double measuredSourceBin =\n                (1.0 - fraction) * trueSourceBins_[li]\n                + fraction * trueSourceBins_[ui];\n            const double transportedBin = measuredSourceBin * safeRatio;\n\n            double& outputPhase = layer.synthesisPhases[\n                static_cast<std::size_t>(targetBin)];\n            if (initialiseExperimental)\n                outputPhase = sourcePhase;\n            else\n            {\n                outputPhase += expectedPhaseScale * transportedBin;\n                outputPhase -= twoPi * std::nearbyint(outputPhase / twoPi);\n            }\n\n            float phaseSine = 0.0f;\n            float phaseCosine = 1.0f;\n            fastSinCos(outputPhase, phaseSine, phaseCosine);\n            const float outputMagnitude = magnitude * energyScaleExperimental;\n            layer.spectrum[static_cast<std::size_t>(targetBin)] = Complex(\n                outputMagnitude * phaseCosine, outputMagnitude * phaseSine);\n        }\n\n        layer.phaseInitialised = true;\n        layer.spectrum[0] = Complex(layer.spectrum[0].real(), 0.0f);\n        layer.spectrum[static_cast<std::size_t>(positiveBins)] =\n            Complex(layer.spectrum[static_cast<std::size_t>(positiveBins)].real(), 0.0f);\n        for (int bin = 1; bin < positiveBins; ++bin)\n            layer.spectrum[static_cast<std::size_t>(frameSize_ - bin)] =\n                std::conj(layer.spectrum[static_cast<std::size_t>(bin)]);\n\n        fft(layer.spectrum, true);\n        const std::int64_t outputStartSample = frameEndSample + 1;\n        for (int index = 0; index < frameSize_; ++index)\n        {\n            const float output = layer.spectrum[static_cast<std::size_t>(index)].real()\n                               * window_[static_cast<std::size_t>(index)];\n            const int outputIndex = static_cast<int>((outputStartSample + index)\n                                                      & outputRingMask_);\n            layer.outputAccumulationRing[static_cast<std::size_t>(outputIndex)] += output;\n        }\n        return;\n    }\n\n    const bool initialiseLayer = resetPhases || !layer.phaseInitialised;'''
assert needle in s
s=s.replace(needle,insert,1)
p.write_text(s)
print('EXPERIMENTAL_TARGET_CENTRIC_FULL_SPECTRUM_PROBE=PASS')
